const express = require('express');
const app = express();
const mysql = require('mysql2/promise');
const mysql2 = require('mysql2/promise');

const db = await mysql.createConnection({
  host: 'localhost',
  user: 'root',
  password: 'password',
  database: 'quotenv'
});

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.post('/reservieren', async (req, res) => {
  const { cpu, speicher } = req.body;
  const reservierung = await db.query(`INSERT INTO reservierungen (cpu, speicher) VALUES (?, ?)`, [cpu, speicher]);
  res.json({ reservierung });
});

app.listen(3000, () => {
  console.log('Server gestartet auf Port 3000');
});
