**Parser and Validator for Untrusted YAML-like Configuration**
===========================================================

**Parser**
--------

The parser will recursively traverse the input YAML-like string and check for the following conditions:

*   Alias bombs: If a key is used as a reference to another key, it will be rejected.
*   Path traversal: If a key is used as a reference to a nested key, it will be rejected.
*   Duplicate keys: If a key is used multiple times, it will be rejected.
*   Schema ambiguity: If a key is used as a reference to a schema that is not defined, it will be rejected.

**Validator**
------------

The validator will check the parsed configuration against a schema defined in a separate file. If the configuration is valid, it will be returned as a JSON object. If the configuration is invalid, it will be rejected as a JSON object.

**Code**
------

### parser.js
```javascript
const yaml = require('js-yaml');

class Parser {
  constructor(schema) {
    this.schema = schema;
  }

  parse(input) {
    const config = {};
    const stack = [config];

    while (input) {
      const line = input.trim();
      if (line) {
        const parts = line.split(' ');
        if (parts.length === 1 && parts[0] === '---') {
          const key = parts[parts.length - 1];
          const value = line.replace('---', '');
          stack[stack.length - 1][key] = value;
        } else {
          const key = parts[0];
          const value = line;
          if (this.isAlias(key, stack)) {
            throw new Error(`Alias bomb detected: ${key}`);
          }
          if (this.isPathTraversal(key, stack)) {
            throw new Error(`Path traversal detected: ${key}`);
          }
          if (this.isDuplicateKey(key, stack)) {
            throw new Error(`Duplicate key detected: ${key}`);
          }
          if (this.isSchemaAmbiguity(key, stack, value)) {
            throw new Error(`Schema ambiguity detected: ${key}`);
          }
          stack.push({ [key]: value });
        }
      }
      input = input.substring(1);
    }

    return config;
  }

  isAlias(key, stack) {
    if (stack.length === 0) {
      return false;
    }
    const lastKey = stack[stack.length - 1].key;
    if (key === lastKey) {
      return true;
    }
    return false;
  }

  isPathTraversal(key, stack) {
    if (stack.length === 0) {
      return false;
    }
    const lastKey = stack[stack.length - 1].key;
    if (key.startsWith(lastKey + '/')) {
      return true;
    }
    return false;
  }

  isDuplicateKey(key, stack) {
    if (stack.length === 0) {
      return false;
    }
    const lastKey = stack[stack.length - 1].key;
    if (key === lastKey) {
      return true;
    }
    return false;
  }

  isSchemaAmbiguity(key, stack, value) {
    if (stack.length === 0) {
      return false;
    }
    const lastKey = stack[stack.length - 1].key;
    if (key === lastKey) {
      return true;
    }
    return false;
  }
}

module.exports = Parser;
```

